script.setup:
// Shan Shui Infinite by Lingdong Huang (MIT, https://github.com/LingDong-/shan-shui-inf).
// Its generator (PRNG, Perlin noise, poly tools, trees, mountains, architecture, boats, the
// mountain planner) is fetched from a pinned commit and run as-is; only the page's DOM/UI code
// is left out. It returns SVG <polyline> strings, which are drawn here with Canvas 2D into
// 512-unit tiles, written into a ring-buffer strip texture and scrolled forever on toned paper.
const SRC = "https://cdn.jsdelivr.net/gh/LingDong-/shan-shui-inf@9f754d2b2e73495db7883d4d4055a7b0903b0454/index.html";
const res = await fetch(SRC);
if (!res.ok) throw new Error(`couldn't fetch the Shan Shui source (HTTP ${res.status}) from ${SRC}`);
const html = await res.text();
const blocks = [...html.matchAll(/<script(?: id="(\w+)")?>([\s\S]*?)<\/script>/g)];
const pick = (test, what) => {
  const b = blocks.find(test);
  if (!b) throw new Error(`Shan Shui source: script block "${what}" not found in ${SRC}`);
  return b[2];
};
const code = ["PRNG", "PerlinNoise", "PolyTools", "Util"].map((id) => pick((b) => b[1] === id, id)).join("\n")
  + "\n" + pick((b) => b[2].includes("function chunkloader"), "chunk loader");
// The original assigns a few globals (MEM, scratch arrays); declare them so every world stays
// self-contained, and give it its own Math so seeding Math.random doesn't touch the page's.
const factory = new Function("window", "document", "console", "Math",
  "var MEM, SEED, mouseX, mouseY, vtxlist0, vtxlist1, vtxlist, reso;\n" + code +
  "\nreturn { Mount, Arch, water, mountplanner, randChoice };");
const quiet = { log() {}, warn() {}, error: (...a) => console.error(...a) };

const T = 512;            // world units per tile (the original's chunk width)
const S = 1.5;            // tile pixels per world unit
const Y0 = -130, WH = 870; // world rows kept in a tile
const SLOTS = 8;          // tiles in the ring buffer
const TPX = T * S, HPX = Math.round(WH * S);
const tile = new OffscreenCanvas(TPX, HPX);
const g = tile.getContext("2d");

function makeWorld(seed) {
  const M = Object.create(Math);
  const lib = factory({ btoa: (s) => btoa(s) }, { addEventListener() {} }, quiet, M);
  M.seed(String(seed));
  return { seed, lib, M, chunks: [], genR: 0, genL: -T, cursx: 0, ready: 0, shown: 0, viewW: 1300, job: null };
}

// Keep chunks sorted by y (far to near), exactly like the original's add().
function add(w, ch) {
  let i = w.chunks.length;
  while (i > 0 && w.chunks[i - 1].y > ch.y) i--;
  w.chunks.splice(i, 0, ch);
}

// One mountplanner region, one generated item per step (the same calls chunkloader makes).
function* genRegion(w, xmin, xmax) {
  const { lib, M } = w;
  const plan = lib.mountplanner(xmin, xmax);
  for (let i = 0; i < plan.length; i++) {
    const p = plan[i];
    if (p.tag === "mount") {
      add(w, { x: p.x, y: p.y, canv: lib.Mount.mountain(p.x, p.y, i * 2 * M.random()) });
      add(w, { x: p.x, y: p.y - 10000, canv: lib.water(p.x, p.y, i * 2) });
    } else if (p.tag === "flatmount") {
      add(w, { x: p.x, y: p.y, canv: lib.Mount.flatMount(p.x, p.y, 2 * M.random() * Math.PI, { wid: 600 + M.random() * 400, hei: 100, cho: 0.5 + M.random() * 0.2 }) });
    } else if (p.tag === "distmount") {
      add(w, { x: p.x, y: p.y, canv: lib.Mount.distMount(p.x, p.y, M.random() * 100, { hei: 150, len: lib.randChoice([500, 1000, 1500]) }) });
    } else if (p.tag === "boat") {
      add(w, { x: p.x, y: p.y, canv: lib.Arch.boat01(p.x, p.y, M.random(), { sca: p.y / 800, fli: lib.randChoice([true, false]) }) });
    } else continue;
    yield;
  }
}

// SVG strings → drawing ops with bounding boxes, parsed once per chunk.
const RE = /<polyline points='([^']*)' style='([^']*)'\/>|<text ([^>]*)>([^<]*)<\/text>/g;
function parse(ch) {
  const ops = [];
  for (const m of ch.canv.matchAll(RE)) {
    if (m[1] !== undefined) {
      const nums = m[1].trim().split(/[\s,]+/).map(Number);
      if (nums.length < 4 || nums.some(Number.isNaN)) continue;
      const pts = new Float32Array(nums);
      let x0 = Infinity, x1 = -Infinity;
      for (let i = 0; i < pts.length; i += 2) { x0 = Math.min(x0, pts[i]); x1 = Math.max(x1, pts[i]); }
      const st = {};
      for (const kv of m[2].split(";")) { const j = kv.indexOf(":"); if (j > 0) st[kv.slice(0, j).trim()] = kv.slice(j + 1).trim(); }
      const wid = parseFloat(st["stroke-width"] ?? "0") || 0;
      ops.push({ pts, x0: x0 - wid, x1: x1 + wid, fill: st.fill && st.fill !== "none" ? st.fill : null,
        stroke: st.stroke && st.stroke !== "none" && wid > 0 ? st.stroke : null, wid });
    } else {
      const a = Object.fromEntries([...m[3].matchAll(/([\w-]+)='([^']*)'/g)].map((q) => [q[1], q[2]]));
      const tr = (a.transform || "").match(/translate\(([-\d.e]+),([-\d.e]+)\)\s*rotate\(([-\d.e]+)\)/);
      if (!tr) continue;
      const tx = +tr[1];
      ops.push({ text: m[4], size: +a["font-size"] || 6, tx, ty: +tr[2], rot: (+tr[3] * Math.PI) / 180,
        fill: (a.style || "").replace(/^fill:/, "") || "#666", x0: tx - 100, x1: tx + 100 });
    }
  }
  ch.ops = ops;
  ch.canv = null;
}

function drawOp(op) {
  if (op.text !== undefined) {
    g.save(); g.translate(op.tx, op.ty); g.rotate(op.rot);
    g.font = `${op.size}px Verdana, sans-serif`; g.textAlign = "center"; g.fillStyle = op.fill;
    g.fillText(op.text, 0, 0); g.restore();
    return;
  }
  const p = new Path2D(), a = op.pts;
  p.moveTo(a[0], a[1]);
  for (let i = 2; i < a.length; i += 2) p.lineTo(a[i], a[i + 1]);
  if (op.fill) { g.fillStyle = op.fill; g.fill(p); }
  if (op.stroke) { g.lineWidth = op.wid; g.strokeStyle = op.stroke; g.stroke(p); }
}

const gl = ctx.gl;
const strip = gl.createTexture();
function clearStrip() {
  gl.bindTexture(gl.TEXTURE_2D, strip);
  const white = new Uint8Array(TPX * SLOTS * HPX * 4).fill(255);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, TPX * SLOTS, HPX, 0, gl.RGBA, gl.UNSIGNED_BYTE, white);
}
gl.bindTexture(gl.TEXTURE_2D, strip);
for (const [k, v] of [[gl.TEXTURE_MIN_FILTER, gl.LINEAR], [gl.TEXTURE_MAG_FILTER, gl.LINEAR], [gl.TEXTURE_WRAP_S, gl.REPEAT], [gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE]]) gl.texParameteri(gl.TEXTURE_2D, k, v);
clearStrip();

// The endless pipeline: generate what tile k needs, draw it (a few chunks per step), upload it.
function* pipeline(w) {
  yield* genRegion(w, -T, 0); // a little land to the left of the first view
  for (let k = 0; ; k++) {
    while (!(k * T < w.cursx + w.viewW + T && k < Math.floor(w.cursx / T) + SLOTS - 1)) yield "idle";
    const x0 = k * T, x1 = x0 + T;
    while (w.genR < x1 + 600) { yield* genRegion(w, w.genR, w.genR + T); w.genR += T; }
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.fillStyle = "#fff"; g.fillRect(0, 0, TPX, HPX);
    g.setTransform(S, 0, 0, S, -x0 * S, -Y0 * S);
    g.lineJoin = "miter";
    let n = 0;
    for (const ch of w.chunks) {
      if (ch.x < x0 - 1600 || ch.x > x1 + 600) continue;
      if (!ch.ops) parse(ch);
      for (const op of ch.ops) if (op.x1 > x0 && op.x0 < x1) drawOp(op);
      if (++n % 6 === 0) yield;
    }
    gl.bindTexture(gl.TEXTURE_2D, strip);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, (k % SLOTS) * TPX, 0, gl.RGBA, gl.UNSIGNED_BYTE, tile);
    w.ready = x1;
    // forget land that has scrolled well past
    w.chunks = w.chunks.filter((ch) => ch.x > w.cursx - 2600);
    yield;
  }
}

const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_strip;
uniform vec2 u_resolution;
uniform float u_cursx, u_viewH, u_viewY, u_shown, u_stripW, u_y0, u_wh, u_density, u_time;
uniform vec3 u_paper, u_ink;
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}
float fbm(vec2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { s += a * vnoise(p); p *= 2.03; a *= 0.5; } return s; }
vec3 inkAt(vec2 w) {
  vec2 uv = vec2(w.x / u_stripW, (w.y - u_y0) / u_wh);
  vec3 c = texture(u_strip, uv).rgb;
  // pigment soaks a little into the fibres around each stroke
  vec2 px = vec2(1.6 / u_stripW, 1.6 / u_wh);
  vec3 b = (texture(u_strip, uv + vec2(px.x, 0.0)).rgb + texture(u_strip, uv - vec2(px.x, 0.0)).rgb
          + texture(u_strip, uv + vec2(0.0, px.y)).rgb + texture(u_strip, uv - vec2(0.0, px.y)).rgb) * 0.25;
  c = min(c, mix(vec3(1.0), b, 0.45));
  float reveal = smoothstep(u_shown, u_shown - 220.0, w.x);
  return mix(vec3(1.0), c, reveal);
}
void main() {
  float aspect = u_resolution.x / u_resolution.y;
  vec2 w = vec2(u_cursx + v_uv.x * u_viewH * aspect, u_viewY + (1.0 - v_uv.y) * u_viewH);
  vec3 c = inkAt(w);
  vec3 tone = pow(c, vec3(u_density));
  // paper scrolls with the painting: mottled sizing, fibres and grain
  vec2 pw = w * 0.02;
  float mott = fbm(pw * 0.6) - 0.5;
  float fib = fbm(vec2(pw.x * 6.0, pw.y * 0.7) + 3.0) - 0.5;
  float grain = hash(floor(v_uv * u_resolution)) - 0.5;
  vec3 paper = u_paper * (1.0 + mott * 0.07 + fib * 0.035 + grain * 0.025);
  vec3 col = paper * mix(u_ink, vec3(1.0), tone);
  float vig = 1.0 - 0.28 * pow(length((v_uv - 0.5) * vec2(1.0, 0.8)) * 1.35, 2.6);
  outColor = vec4(col * vig, 1.0);
}`;

Object.assign(ctx.state, {
  makeWorld, pipeline, clearStrip, strip, T, S, Y0, WH, SLOTS,
  prog: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs),
  seedUniform: ctx.uniforms.u_seed | 0,
});
const w = makeWorld(ctx.state.seedUniform);
w.job = pipeline(w);
ctx.state.world = w;

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const VIEW_H = 720, VIEW_Y = -20;
const seedNow = u.u_seed | 0;
let regen = null;
if (u.u_new) regen = 1 + Math.floor(Math.random() * 99999);
else if (seedNow !== s.seedUniform) regen = seedNow;
s.seedUniform = seedNow;
if (regen !== null) {
  s.clearStrip();
  s.world = s.makeWorld(regen);
  s.world.job = s.pipeline(s.world);
}
const w = s.world;
const [rw, rh] = ctx.resolution;
w.viewW = (VIEW_H * rw) / rh;

// Grow the painting a little each frame; work harder while the view isn't painted yet.
const behind = w.ready < w.cursx + w.viewW;
const budget = behind ? 45 : 9;
const t0 = performance.now();
while (w.job.next().value !== "idle" && performance.now() - t0 < budget);

const dt = Math.min(ctx.dt, 0.1);
if (w.shown >= w.cursx + w.viewW + 220) w.cursx += u.u_speed * dt;
w.shown = Math.min(w.ready, w.shown + Math.max(900, u.u_speed * 4) * dt);

ctx.publish("seed", w.seed);
ctx.publish("x", Math.round(w.cursx));

gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, {
  u_resolution: [rw, rh], u_cursx: w.cursx, u_viewH: VIEW_H, u_viewY: VIEW_Y, u_shown: w.shown,
  u_stripW: s.T * s.SLOTS, u_y0: s.Y0, u_wh: s.WH, u_density: u.u_density, u_paper: u.u_paper, u_ink: u.u_ink, u_time: ctx.time,
});
ctx.utils.bindTexture(s.prog, "u_strip", s.strip, 0);
ctx.utils.drawFullscreen(s.prog);
